function sum(multiplier = 1, ...numbers) {
  return numbers.reduce((total, n) => total + n, 0) * multiplier;
}
console.log(sum(2, 1, 2, 3));

const addTax = price => price * 1.1;
const roundMoney = value => Math.round(value * 100) / 100;
const finalPrice = price => roundMoney(addTax(price));
console.log(finalPrice(19.99));
